snippet_css:
:root{
  --bg: #1B1436;
  --fg: #FFFFFF;
  --muted: #E4E0F2;
  --surface: rgba(255,255,255,.12);
  --border: rgba(255,255,255,.30);
  --accent: #B79CFF;
  --accent-fg: #191136;
  --accent-grad: linear-gradient(135deg,#B79CFF,#7FE6E0);
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 20px 50px rgba(9,4,24,.45),inset 0 1px 0 rgba(255,255,255,.28);
  --btn-shadow: 0 10px 26px rgba(183,156,255,.30);
  --art-bg: linear-gradient(135deg,rgba(255,255,255,.42),rgba(255,255,255,.06));
  --media-bg: linear-gradient(135deg,rgba(127,90,240,.55),rgba(44,182,125,.35));
  --cta-bg: rgba(255,255,255,.10);
  --input-bg: rgba(255,255,255,.14);
  --ok: #8BE8C0;
  --warn: #FFA893;
  --font-display: 'Plus Jakarta Sans','Noto Sans TC',sans-serif;
  --font-body: 'Plus Jakarta Sans','Noto Sans TC',sans-serif;
  --font-mono: ui-monospace,'SF Mono',Menlo,monospace;
  --focus-ring: var(--accent);
}

